#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNativeEngine: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = NativeEngine

    public static func lift(_ handle: UInt64) throws -> NativeEngine {
        return NativeEngine(unsafeFromHandle: handle)
    }

    public static func lower(_ value: NativeEngine) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NativeEngine {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: NativeEngine, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNativeEngine_lift(_ handle: UInt64) throws -> NativeEngine {
    return try FfiConverterTypeNativeEngine.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNativeEngine_lower(_ value: NativeEngine) -> UInt64 {
    return FfiConverterTypeNativeEngine.lower(value)
}






/**
 * Foreign aliases share this single serialized owner. No callback API is exported;
 * owned synchronous results precede the next submission and survive disposal.
 */
public protocol NativeSessionProtocol: AnyObject, Sendable {
    
    func cancelCommands(token: String) throws 
    
    /**
     * Ordered idempotent release of an uncommitted plan. After disposal: Disposed.
     */
    func cancelEdits(token: String) throws 
    
    /**
     * Capture all endpoints against one observed revision. Validate every target
     * before retaining anything, so an invalid endpoint cannot leak anchor slots.
     */
    func captureAnchors(revision: Data, inputs: [AnchorInput]) throws  -> [NativeSessionAnchor]
    
    /**
     * Exact current target applicability via the authoritative planner; retains no plan.
     */
    func checkCommands(revision: Data, commandsJson: String, origin: String, now: UInt64) throws 
    
    /**
     * Detached current metadata. Target-specific enablement requires check_commands.
     */
    func commandCatalog(now: UInt64) throws  -> NativeCommandCatalog
    
    func commitCommands(token: String, now: UInt64) throws  -> NativeSessionCommit?
    
    /**
     * Single use, including failed admission. Current permission/revision is checked
     * again by EditService. Cancellation cannot interrupt an accepted commit.
     */
    func commitEdits(token: String, now: UInt64) throws  -> NativeSessionCommit?
    
    /**
     * Idempotent across aliases. Waits for accepted work and drops the real Session,
     * all plans and native store on the owning executor before returning.
     */
    func dispose() throws 
    
    /**
     * Exact stack availability for native menus/keys. The observation is advisory:
     * undo/redo still recheck current permission, admission and the supplied revision.
     * Disposal returns Disposed, as with every other read on this handle.
     */
    func historyState(now: UInt64) throws  -> NativeSessionHistory
    
    /**
     * Owned committed outbox records; frozen Sessions cannot publish pending updates.
     */
    func pendingUpdates() throws  -> [NativeSessionPeerUpdate]
    
    /**
     * Same portable EditorCommand array and anchor tokens as the shared engine.
     * All parsing, anchor lookup and EditService validation precede retaining a plan.
     */
    func prepareCommands(revision: Data, commandsJson: String, origin: String, now: UInt64) throws  -> NativePreparedCommands
    
    /**
     * Whole-edit batches use the existing atomic EditService planner. Revision bytes
     * are equality validators supplied by read(), never authorization credentials.
     */
    func prepareEdits(revision: Data, edits: [NativeSessionEdit], origin: String, now: UInt64) throws  -> String
    
    func read(now: UInt64) throws  -> NativeSessionRead
    
    /**
     * Trusted-host ingress over the actual EditService/Session, after host security admission.
     * This accepts neither unauthenticated network frames nor encrypted packets.
     */
    func receivePeer(update: NativeSessionPeerUpdate) throws  -> NativeSessionCommit
    
    func recover() throws 
    
    func recoveryExport() throws  -> NativeSessionRecovery
    
    func redo(revision: Data, now: UInt64) throws  -> NativeSessionCommit?
    
    /**
     * Idempotent for unknown/foreign tokens; cleanup is available during recovery.
     */
    func releaseAnchor(token: String) throws 
    
    /**
     * Trusted host reserves an actual peer writer once, never an authentication grant.
     */
    func reservePeerWriter(writer: UInt32) throws 
    
    /**
     * Resolve the retained shared sticky position against the current committed
     * revision, including deleted and unresolvable outcomes without local fallback.
     */
    func resolveAnchor(token: String) throws  -> NativeSessionAnchorRead
    
    /**
     * Establish/reset this handle's incremental cursor. Recovery-required state
     * cannot mint an acknowledged projection; salvage remains recoveryExport.
     */
    func richSnapshot() throws  -> NativeSessionProjection
    
    /**
     * Read a bounded byte window of the exact authoritative rich JSON.
     * Only successful completion acknowledges the snapshot's patch sequence.
     */
    func richSnapshotChunk(expectedRevision: Data, offsetBytes: UInt64) throws  -> NativeSessionProjectionChunk
    
    /**
     * Trusted host opt-in for bounded inert image/reference edits. This grants
     * neither write permission nor network/resolver authority, and is not stored.
     */
    func setAtomicContentPolicy(images: Bool, references: Bool) throws 
    
    /**
     * Opt in to registered marks/atoms and bounded inert source editing. No typesetting.
     */
    func setExtensionPolicy(enabled: Bool) throws 
    
    /**
     * Trusted host permission replacement, serialized with every prepared admission.
     */
    func setPermission(writable: Bool, expiresAt: UInt64?) throws 
    
    /**
     * Trusted host table codec policy, independent of write permission. Defaults
     * to disabled on every create/open. Retained plans recheck it at commit.
     */
    func setTablePolicy(enabled: Bool) throws 
    
    /**
     * A single bounded consumer shared by all aliases. Failed reads never drain.
     * Overflow requires richSnapshot; no event is silently omitted or coalesced.
     */
    func takeRichPatches(afterSequence: UInt64) throws  -> NativeSessionPatches
    
    func undo(revision: Data, now: UInt64) throws  -> NativeSessionCommit?
    
    /**
     * Exact authenticated application receipt; only the existing atomic store path prunes.
     */
    func acceptHostReceipt(token: String, receipt: NativeHostReceipt, now: UInt64) throws  -> NativeHostReceiptResult
    
    /**
     * Trusted host grants an exclusive lease, with no local write permission change.
     */
    func attachHostTransport(options: NativeHostTransportOptions, now: UInt64) throws  -> String
    
    /**
     * Detach/revoke only this connection. A stale event cannot revoke a newer lease.
     */
    func detachHostTransport(token: String) throws 
    
    /**
     * Existing Session y-protocols flush. Partial queueing on backpressure is retained.
     */
    func flushHostTransport(token: String, now: UInt64) throws  -> UInt64
    
    /**
     * Page over exact durable pending identities without manufacturing receipts.
     */
    func flushHostTransportPage(token: String, after: NativeHostReceipt?, maxFrames: UInt32, now: UInt64) throws  -> UInt64
    
    /**
     * Existing trusted-host journal admission, additionally bound to the active lease.
     */
    func receiveHostPeer(token: String, update: NativeSessionPeerUpdate, now: UInt64) throws  -> NativeSessionCommit
    
    /**
     * Pull copied outbound frames; delivery is never a remote durable acknowledgment.
     */
    func takeHostFrames(token: String, maxFrames: UInt32, now: UInt64) throws  -> [NativeHostFrame]
    
    /**
     * Queue a coalesced pinned awareness frame; queue backpressure retains state.
     */
    func flushHostPresence(token: String, now: UInt64) throws  -> Bool
    
    /**
     * Resolve relative cursors against current committed content, expiring peers.
     */
    func hostPresence(token: String, now: UInt64) throws  -> [NativePeerPresence]
    
    /**
     * Host authenticates participant routing before supplying the existing wire.
     */
    func receiveHostPresence(token: String, frame: NativeHostFrame, now: UInt64) throws 
    
    /**
     * None means online without selection; present=false emits an explicit leave.
     * Both tokens must belong to this worker. No local permission is granted.
     */
    func setHostPresence(token: String, anchor: String?, focus: String?, present: Bool, now: UInt64) throws 
    
    /**
     * Awareness uses a separate bounded owning transport queue from durable sync.
     */
    func takeHostPresenceFrames(token: String, maxFrames: UInt32, now: UInt64) throws  -> [NativeHostFrame]
    
    /**
     * Explicit acknowledged-state capture; never called from typing/edit/history hooks.
     */
    func captureReviewRevision(revision: Data, name: String, requiredKeyProfile: String?) throws  -> NativeReviewRevision
    
    func compareReviewRevisions(before: NativeReviewRevision, after: NativeReviewRevision, beforeKeyProfile: String?, afterKeyProfile: String?, maxBytes: UInt64) throws  -> NativeReviewComparison
    
    func readReviewRevision(revision: NativeReviewRevision, availableKeyProfile: String?) throws  -> NativeReviewRead
    
    /**
     * Tightening immediately prunes; widening cannot recreate evicted history.
     */
    func setReviewRetention(maxRevisions: UInt32, maxTotalBytes: UInt64) throws 
    
    /**
     * Canonical shared decoder/validator. No native semantic parser or author inference.
     */
    func validateChangeModel(bytes: Data, maxBytes: UInt64) throws  -> NativeChangeModel
    
    func cancelTransfer(token: String) throws 
    
    /**
     * Ordinary paste never deletes a source. For cut, acknowledge the clipboard;
     * for cross-document deletion, supply an opaque qualified destination receipt.
     * Every attempt consumes the plan, including rejected or stale admission.
     */
    func commitTransfer(token: String, clipboardAcknowledged: Bool, destinationReceipt: NativeTransferReceipt?, now: UInt64) throws  -> NativeTransferCommit
    
    func exportTransfer(revision: Data, range: NativeTransferRange, now: UInt64) throws  -> NativeTransferExport
    
    func prepareCut(revision: Data, range: NativeTransferRange, now: UInt64) throws  -> NativePreparedTransfer
    
    func preparePaste(revision: Data, range: NativeTransferRange, input: NativeTransferInput, source: NativeTransferSource?, now: UInt64) throws  -> NativePreparedTransfer
    
    func prepareTransferMove(revision: Data, source: NativeTransferRange, destination: NativeTransferRange, now: UInt64) throws  -> NativePreparedTransfer
    
    /**
     * Trusted host registration of the existing callout codec. No resolver or
     * network authority; retained transfers recheck this setting at admission.
     */
    func setCalloutPolicy(enabled: Bool) throws 
    
}
