    case Locked
    case Unauthorized
    case Incompatible
    case ReadOnly
    case PermissionExpired
    case RecoveryRequired
    case HistoryView
    case UnqualifiedHistory
    case UnsupportedModule
    case ResourceLimit
    case Engine(message: String
    )
    case Source(message: String
    )
    case Operation(message: String
    )
    case InvalidPlan
    case Disposed
    case ExecutorUnavailable
    case ProjectionResyncRequired
    case InvalidProjectionCursor
    case InvalidAnchor
    case AnchorTarget(message: String
    )
    case CommandInput(message: String
    )
    case ReviewInput(reason: NativeReviewFailure
    )

    

    

    
